mapper.select:
SELECT n.id, n.sender_id AS senderId, u.nickname AS senderName,
u.avatar AS senderAvatar, n.type, n.target_id AS targetId,
n.target_type AS targetType, n.title, n.content,
n.is_read AS isRead, n.create_time AS createTime
FROM notification n
LEFT JOIN user u ON u.id = n.sender_id
WHERE n.user_id = #{userId}
AND n.deleted = 0

    AND n.type = #{type}


    AND n.is_read = #{isRead}

ORDER BY n.create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM notification
WHERE user_id = #{userId} AND deleted = 0

    AND type = #{type}


    AND is_read = #{isRead}

mapper.update:
UPDATE notification
SET deleted = 1
WHERE id = #{id} AND user_id = #{userId}

mapper.select:
SELECT id, user_id, sender_id, type, target_id, target_type,
       title, content, is_read, deleted, create_time
FROM notification
WHERE user_id = #{authorId}
  AND sender_id = #{senderId}
  AND target_id = #{articleId}
  AND type = 1
  AND target_type = 1
  AND deleted = 0
LIMIT 1

mapper.delete:
DELETE FROM notification
WHERE user_id = #{authorId}
  AND sender_id = #{senderId}
  AND target_id = #{articleId}
  AND type = 1
  AND target_type = 1
